  approaches: [{ name: 'O(1) Space Markers', complexity: { time: 'O(m×n)', space: 'O(1)' }, description: 'Use matrix edges as flags.', pseudocode: 'Mark first row/col if they have zeros\nUse first row/col to mark other zeros\nZero marked rows/cols\nHandle first row/col last' }],
  dryRun: { input: 'matrix=[[1,1,1],[1,0,1],[1,1,1]]', steps: [{ step: 1, state: 'Found 0 at (1,1)', action: 'Mark matrix[1][0]=0, matrix[0][1]=0' }, { step: 2, state: 'Second pass', action: 'Zero row 1 and col 1 → [[1,0,1],[0,0,0],[1,0,1]] ✓' }] },
  edgeCases: [{ case: 'No zeros', explanation: 'Matrix unchanged' }, { case: 'All zeros', explanation: 'Stay all zeros' }, { case: 'Single element [[0]]', explanation: 'Already zero' }, { case: 'Zero in corner', explanation: 'Entire row and column zeroed' }, { case: '1x1 matrix [[5]]', explanation: 'No zeros, unchanged' }],
